<?php if($item['type']==='tier'): ?><strong class="club-price">Proposed $<?= number_format(((int)$row['monthly_cents'])/100,2) ?><span>/month</span></strong><p><?= nl2br(az_h($row['description'])) ?></p><?php else: ?><p class="club-help"><strong>Audience:</strong> <?= ($row['audience']??'tier')==='followers'?'Free followers':'Members with access to the selected tier' ?></p><p><?= nl2br(az_h($row['body'])) ?></p><?php if($row['media_id']): ?><video controls playsinline preload="metadata" src="creator-club-media.php?post=<?= az_h($row['id']) ?>" aria-label="Private footage submitted for review"></video><?php endif; ?><?php if(!empty($row['publish_at'])): ?><div class="club-release-note"><span aria-hidden="true">◷</span><div><strong>Requested release</strong><p><?= az_h(az_creator_club_schedule_label($row)) ?></p><small>Approval keeps a future release private until its scheduled time. If this time has passed, approval publishes the post now.</small></div></div><?php else: ?><p class="club-help"><strong>Release:</strong> Publish after approval.</p><?php endif; ?><p class="club-help">Creator declaration: <?= (int)($row['rights_confirmed']??0)===1?'rights confirmed':'RIGHTS NOT CONFIRMED' ?>. Review participant consent and any private video before approval.</p><?php endif; ?>
